import{_ as t,o as p,c as n,y as e}from"./chunks/framework.CNTkXYA8.js";const _=JSON.parse('{"title":"【Ubuntu】无法挂载磁盘","description":"","frontmatter":{"title":"【Ubuntu】无法挂载磁盘","date":"2018-12-08T10:20:00.000Z"},"headers":[],"relativePath":"blog/ubuntu-10086672.md","filePath":"source/old_posts/ubuntu-10086672.md"}'),a={name:"blog/ubuntu-10086672.md"};function i(o,s,u,d,l,r){return p(),n("div",null,[...s[0]||(s[0]=[e('<p>我的电脑分了三个分区，A，B，C，其中A和B是Windows盘，C是ubuntu系统盘</p><p>某日发现A ,B盘没法进入了，在文件管理器中点一下，没有反应。于是右击盘符，点击挂载，跳出错误信息：</p><p><img src="https://img2018.cnblogs.com/blog/1389232/201812/1389232-20181208101446822-824525432.png" alt=""></p><p>（划重点）</p><p>于是输入：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ntfsfix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/nvme0n1p3</span></span></code></pre></div><p>然后可以访问了。</p><p>于是同样方法对于装Windows的系统盘，但是不成功！</p><p>上网查了一下，应该是新版本的Windows（10）会在你关机之后继续运行，然后我启动了Ubuntu，所以只能挂载非系统盘。</p><p>但是通常情况下不会出现这种情况，回忆一下经过：</p><p>昨天晚上用完电脑，关机（Windows关机）。</p><p>今天早上打开Ubuntu。</p><p>得出结论：Windows估计后台在更新或者别的什么；或者是WinDefender在查杀什么的。</p><p>解决办法：重启成Windows，然后重启为Ubuntu。</p>',14)])])}const b=t(a,[["render",i]]);export{_ as __pageData,b as default};
